from collections import deque
def fill_boxes(g, border, fill):
    """Fill with `fill` every region of non-border cells whose surrounding ring is a complete border-color rectangle."""
    h,w=len(g),len(g[0])
    reach=[[False]*w for _ in range(h)]; q=deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]!=border: reach[i][j]=True; q.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]!=border: reach[i][j]=True; q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and g[ni][nj]!=border and not reach[ni][nj]:
                reach[ni][nj]=True; q.append((ni,nj))
    out=[row[:] for row in g]
    seen=[[False]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if not reach[i][j] and not seen[i][j]:
                comp=[]; s=[(i,j)]; seen[i][j]=True
                while s:
                    a,b=s.pop(); comp.append((a,b))
                    for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+di,b+dj
                        if 0<=na<h and 0<=nb<w and not reach[na][nb] and not seen[na][nb]:
                            seen[na][nb]=True; s.append((na,nb))
                rs=[a for a,_ in comp]; cs=[b for _,b in comp]
                t,l,btm,r=min(rs),min(cs),max(rs),max(cs)
                if t>0 and l>0 and btm<h-1 and r<w-1 and all(
                    g[x][y]==border for x in range(t-1,btm+2) for y in range(l-1,r+2)
                    if x in (t-1,btm+1) or y in (l-1,r+1)):
                    for a,b in comp: out[a][b]=fill
    return out
